torch::Tensor compact_wy_t(torch::Tensor gram, torch::Tensor tau) {
  TORCH_CHECK(gram.is_cuda() && tau.is_cuda(),
              "compact-WY inputs must be CUDA tensors");
  TORCH_CHECK(gram.scalar_type() == torch::kFloat32 &&
              tau.scalar_type() == torch::kFloat32,
              "compact-WY inputs must be FP32");
  TORCH_CHECK(gram.dim() == 3 && gram.size(1) == gram.size(2),
              "Gram input must have shape [batch, width, width]");
  TORCH_CHECK(tau.dim() == 2 && tau.size(0) == gram.size(0) &&
              tau.size(1) == gram.size(1),
              "tau input must have shape [batch, width]");
  TORCH_CHECK(gram.is_contiguous() && tau.is_contiguous(),
              "compact-WY inputs must be contiguous");
  const c10::cuda::CUDAGuard device_guard(gram.device());
  const int batch = static_cast<int>(gram.size(0));
  const int width = static_cast<int>(gram.size(1));
  TORCH_CHECK(width <= 128, "compact-WY width must not exceed 128");
  auto t = torch::empty_like(gram);
  const int shared_bytes = (width * width + 2 * width) * sizeof(float);
  cudaFuncSetAttribute(compact_wy_t_kernel,
                       cudaFuncAttributeMaxDynamicSharedMemorySize,
                       shared_bytes);
  compact_wy_t_kernel<<<batch, 128, shared_bytes>>>(
      gram.data_ptr<float>(), tau.data_ptr<float>(), t.data_ptr<float>(),
      width);
  return t;
}

