def _fixed_refine_n1024(data, vectors, values):
    previous_precision = torch.get_float32_matmul_precision()
    torch.set_float32_matmul_precision("high")
    gram = torch.bmm(vectors.transpose(1, 2), vectors)
    correction = gram.mul(-0.5)
    correction.diagonal(dim1=-2, dim2=-1).add_(1.5)
    vectors = torch.bmm(vectors, correction)
    torch.set_float32_matmul_precision(previous_precision)
    flags = _ext.certify_eigh(data, vectors, values)
    if not bool(flags[-1]):
        return vectors, values

    unsafe_indices = flags[:-1].nonzero().flatten()
    candidate_data = torch.index_select(data, 0, unsafe_indices).contiguous()
    candidate_vectors = torch.index_select(
        vectors, 0, unsafe_indices
    ).contiguous()
    candidate_values = torch.index_select(
        values, 0, unsafe_indices
    ).contiguous()
    torch.set_float32_matmul_precision("high")
    gram = torch.bmm(candidate_vectors.transpose(1, 2), candidate_vectors)
    correction = gram.mul(-0.5)
    correction.diagonal(dim1=-2, dim2=-1).add_(1.5)
    candidate_vectors = torch.bmm(candidate_vectors, correction)
    torch.set_float32_matmul_precision(previous_precision)
    refined_flags = _ext.certify_eigh(
        candidate_data, candidate_vectors, candidate_values
    )
    vectors[unsafe_indices] = candidate_vectors
    if not bool(refined_flags[-1]):
        return vectors, values

    remaining_positions = refined_flags[:-1].nonzero().flatten()
    remaining_indices = torch.index_select(
        unsafe_indices, 0, remaining_positions
    )
    if remaining_indices.numel() * 4 >= data.shape[0] * 3:
        return _ext.xsyev_batched(data)
    repaired_vectors, repaired_values = _ext.xsyev_batched(
        torch.index_select(data, 0, remaining_indices).contiguous()
    )
    vectors[remaining_indices] = repaired_vectors
    values[remaining_indices] = repaired_values
    return vectors, values


def _recover_tridiagonal_basis_n1024(vectors, values):
    batch, n, _ = vectors.shape
    scale = values.abs().amax(dim=1)
    threshold = 64.0 * torch.finfo(values.dtype).eps * (1.0 + scale)
    joined = (values[:, 1:] - values[:, :-1]).abs() <= threshold[:, None]
    buckets = {}
    for matrix, links in enumerate(joined.cpu().tolist()):
        start = 0
        for gap, connected in enumerate(links):
            if connected:
                continue
            width = gap + 1 - start
            if width >= 16:
                buckets.setdefault(width, []).append((matrix, start))
            start = gap + 1
        width = n - start
        if width >= 16:
            buckets.setdefault(width, []).append((matrix, start))

    if not buckets:
        return vectors
    recovered = vectors.clone()
    rows = torch.arange(n, device=vectors.device)
    for width, ranges in buckets.items():
        matrices = torch.tensor(
            [item[0] for item in ranges], device=vectors.device
        )
        starts = torch.tensor(
            [item[1] for item in ranges], device=vectors.device
        )
        columns = starts[:, None] + torch.arange(width, device=vectors.device)
        blocks = vectors[
            matrices[:, None, None], rows[None, :, None], columns[:, None, :]
        ]
        q, _ = torch.linalg.qr(blocks, mode="reduced")
        recovered[
            matrices[:, None, None], rows[None, :, None], columns[:, None, :]
        ] = q
    return recovered.contiguous()


